  /**
   * When a worker last picked the run up, in UTC: the start of its current stretch of execution. While the run is `Active`, its runtime is `executionTime` plus the time since this; while it waits (for a person, an approval or a resume) it is `executionTime` alone, so time spent waiting for a person never counts. Null for capsule runs, and when not recorded.
   *
   * A `Date` (ISO-8601 on the wire).
   */
  dateRunnerClaimed: Date | null;
